-- Part 3 of 5: macro data for nyt_recipes (4300 rows), refreshed after
-- fixing keyword-rule bugs in MACRO_KEYWORD_RULES (index.html): "potato"
-- and "onion" had no plural form so "potatoes"/"onions" never matched
-- despite the singular already being covered, and ginger/orange/plain
-- cream/mint had no rule at all. Supersedes migrations/006 (which itself
-- superseded 005 -- see that file's header for the earlier serving-count
-- bug). Adds 736 newly-covered recipes and corrects undercounted matched-
-- mass on 4529 more. Run all 5 parts, in order.
